suppressPackageStartupMessages(library(data.table));setDTthreads(1)
P<-normalizePath(commandArgs(TRUE)[1]);O<-file.path(P,'84_JCO_PO_Upgrade_20261113/05_analysis/D_biology');d<-fread(file.path(O,'results/D_PRIMARY_GENOTYPE.csv'));d[,cohort:=factor(cohort,levels=c('JAVELIN','IMmotion151','CheckMate025'))];setorder(d,cohort);d[,gene:=factor(gene,levels=c('VHL','PBRM1','BAP1'))];setorder(d,cohort,gene)
png(file.path(O,'plots/primary_genotype_forest.png'),width=1800,height=1250,res=180);par(mar=c(4.4,10,3,2),las=1);ys<-nrow(d):1;plot(NA,xlim=c(-12,10),ylim=c(.5,nrow(d)+.7),xlab='Signed Angio36 displacement (I1 - I0 percentile points)',ylab='',yaxt='n',main='Exploratory upgrade: primary genotype estimands');abline(v=0,lty=2,col='gray65');axis(2,at=ys,labels=paste(d$cohort,d$gene),tick=FALSE);cl<-c('#25657A','#9C5A35','#6C5B83')[as.integer(d$cohort)];segments(d$lower,ys,d$upper,ys,col=cl,lwd=2);points(d$estimate,ys,pch=19,col=cl,cex=1.15);mtext('Adjusted altered-versus-source-negative differences; HC3 95% CI; one BH family of 9 tests',side=3,line=.2,cex=.66);dev.off()
f<-fread(file.path(O,'results/GENE_FLOOR_SD_WEIGHT.csv'))[signature=='Angio36'];png(file.path(O,'plots/floor_weight_diagnostic.png'),width=2000,height=1200,res=180);par(mfrow=c(2,3),mar=c(4,4,2,1));for(co in unique(f$cohort)){z<-f[cohort==co];plot(z$fraction_at_released_minimum,z$weight_I1_relative_I0,log='y',pch=19,col=ifelse(grepl('^FGF',z$gene),'#9C5A35','#25657A'),xlab='Fraction at released minimum',ylab='I1 weight / I0 weight',main=co);abline(h=1,lty=2,col='gray60')};dev.off()
